// n8n Code node "Validate payload"  (Run Once for All Items)
//
// First step after the authenticated Webhook, before Firestore or Gmail. The
// dashboard builds this payload from the stored ticket, but this workflow is a
// public URL protected only by a shared secret, so it checks everything itself.
//
// Output: ONE item.
//   ok: true  -> `p` holds the cleaned values every later node reads.
//   ok: false -> `code` + `body`, ready for the "Respond" node (400). The
//                submitted text is never echoed back.
const raw = $input.first().json;
const b = raw && typeof raw.body === 'object' && raw.body !== null && !Array.isArray(raw.body) ? raw.body : {};
const bad = [];
const CONTROL = /[\u0000-\u001f\u007f]/;
const ID = /^[A-Za-z0-9_-]+$/;

const id = (v, name, min, max) => {
  if (typeof v !== 'string' || v.length < min || v.length > max || !ID.test(v)) {
    bad.push(name);
    return null;
  }
  return v;
};

const ticketId = id(b.ticketId, 'ticketId', 1, 128);
const key = id(b.idempotencyKey, 'idempotencyKey', 8, 128);

const types = ['initial_response', 'follow_up'];
const messageType = types.includes(b.messageType) ? b.messageType : (bad.push('messageType'), null);

// Exactly one plain address: no list, no display name, no line breaks.
let customerEmail = null;
if (typeof b.customerEmail === 'string') {
  const e = b.customerEmail.trim();
  const at = e.indexOf('@');
  const domain = e.slice(at + 1);
  const ok =
    e.length <= 254 &&
    at > 0 &&
    at === e.lastIndexOf('@') &&
    at <= 64 &&
    !CONTROL.test(e) &&
    !/[\s,;<>()"\\]/.test(e) &&
    /^[^.][^\s]*\.[^.\s]+$/.test(domain) &&
    !domain.includes('..') &&
    !e.slice(0, at).includes('..') &&
    !e.startsWith('.') &&
    !e.slice(0, at).endsWith('.');
  if (ok) customerEmail = e;
}
if (!customerEmail) bad.push('customerEmail');

let subject = null;
if (typeof b.subject === 'string' && b.subject.trim() && b.subject.length <= 200 && !CONTROL.test(b.subject)) {
  subject = b.subject.trim();
} else bad.push('subject');

const norm = (s) => String(s).replace(/\r\n?/g, '\n').trim();
let messageBody = null;
if (typeof b.messageBody === 'string' && norm(b.messageBody) && norm(b.messageBody).length <= 10000) {
  messageBody = norm(b.messageBody);
} else bad.push('messageBody');

// Both fields carry the same text for an initial response; a mismatch means the payload was altered.
if (messageType === 'initial_response' && b.finalResponse !== undefined && messageBody !== null && norm(b.finalResponse) !== messageBody) {
  bad.push('finalResponse');
}
if (messageType === 'follow_up' && b.messageId !== undefined && b.messageId !== key) bad.push('messageId');
const attempt = Number.isInteger(b.attempt) && b.attempt >= 1 ? b.attempt : 1;

if (bad.length) {
  return [{ json: { ok: false, code: 400, body: { status: 'failed', error: 'Invalid payload', fields: bad } } }];
}
return [{ json: { ok: true, p: { ticketId, key, messageType, customerEmail, subject, messageBody, attempt } } }];

// n8n Code node "Check ticket"  (Run Once for All Items)
//
// Compares the request with the stored ticket. Nothing has been sent at this
// point, so every refusal here is a certain "not delivered" (status "failed").
const p = $('Validate payload').first().json.p;
const t = $input.first().json ?? {};

const fail = (code, error) => [{ json: { ok: false, code, body: { status: 'failed', error } } }];

// A missing document arrives as an empty item ("Always Output Data"); an error item is a
// genuine read failure, never "not found".
if (t.error !== undefined) return fail(502, 'The ticket could not be read, so nothing was sent');
if (!t._id && !t.customerEmail && !t.reviewStatus) return fail(404, 'Ticket not found');

const norm = (s) => String(s ?? '').replace(/\r\n?/g, '\n').trim();
const same = (a, b) => String(a ?? '').trim().toLowerCase() === String(b ?? '').trim().toLowerCase();

if (!same(t.customerEmail, p.customerEmail)) return fail(409, 'The recipient does not match the ticket');

if (p.messageType === 'initial_response') {
  if (String(t.reviewStatus ?? '').trim().toLowerCase() !== 'approved') return fail(409, 'The response is not approved');
  if (norm(t.finalResponse) !== p.messageBody) return fail(409, 'The text does not match the approved response');
}
return [{ json: { ok: true } }];

// n8n Code node "Decide duplicate"  (Run Once for All Items)
//
// Looks at the two n8n-owned log documents for this idempotency key:
//   n8n_send_log/{key}__sent  exists -> Gmail already sent it: answer "sent", send nothing.
//   n8n_send_log/{key}__a{attempt} exists -> an earlier run of THIS attempt started and may or
//                                       may not have sent it: answer "unknown", send nothing.
//   neither                          -> this run may claim the send.
// The claim is scoped to the attempt number: the dashboard only raises it after an agent
// explicitly resolved an unconfirmed send (or after a known failure), so a resolved message
// can be re-sent, while the "sent" record (all attempts) still blocks a real duplicate.
// A missing document arrives as an EMPTY item ("Always Output Data"). ANY error item, even
// one that mentions "not found", is "unknown": we cannot rule out an earlier send.
const p = $('Validate payload').first().json.p;
const sentRec = $('Get sent record').first().json ?? {};
const claimRec = $('Get claim record').first().json ?? {};

const exists = (j) => j.error === undefined && Object.keys(j).length > 0;
const unknown = (error) => [{ json: { ok: false, code: 200, body: { status: 'unknown', error } } }];

if (exists(sentRec)) {
  return [
    {
      json: {
        ok: false,
        code: 200,
        body: {
          status: 'sent',
          sentAt: typeof sentRec.sentAt === 'string' ? sentRec.sentAt : null,
          messageId: typeof sentRec.gmailId === 'string' ? sentRec.gmailId : null,
          deduplicated: true,
        },
      },
    },
  ];
}
if (sentRec.error !== undefined) return unknown('The send log could not be read');
if (exists(claimRec)) return unknown('An earlier attempt did not finish');
if (claimRec.error !== undefined) return unknown('The send log could not be read');

// Fields the "Create claim" node stores.
return [{ json: { ok: true, status: 'sending', startedAt: new Date().toISOString(), ticketId: p.ticketId, messageType: p.messageType, attempt: p.attempt } }];

// n8n Code node "Claim failed"  (Run Once for All Items)
// The send log refused the claim (the document already exists, or Firestore failed).
// Either way nothing was sent by THIS run, but an earlier run may have, so answer "unknown".
return [{ json: { code: 200, body: { status: 'unknown', error: 'The send could not be claimed' } } }];

// n8n Code node "Prepare sent record"  (Run Once for All Items)
// Gmail has accepted the message. Builds the log document that makes every later
// repeat of this idempotency key answer "sent" without emailing again.
const p = $('Validate payload').first().json.p;
const gmail = $input.first().json ?? {};
return [
  {
    json: {
      status: 'sent',
      sentAt: new Date().toISOString(),
      gmailId: typeof gmail.id === 'string' ? gmail.id : null,
      ticketId: p.ticketId,
      messageType: p.messageType,
    },
  },
];

// n8n Code node "Build sent response"  (Run Once for All Items)
// Answer for a message Gmail accepted. Reached even if writing the log failed,
// because the email WAS sent and the dashboard must record that.
const rec = $('Prepare sent record').first().json;
return [{ json: { code: 200, body: { status: 'sent', sentAt: rec.sentAt, messageId: rec.gmailId } } }];

// n8n Code node "Classify Gmail error"  (Run Once for All Items)
//
// Gmail's error output does NOT always prove nothing was sent (a timeout can follow a
// successful send). Only an immediate, explicit rejection is "failed": a bad request
// (400), or an authentication/permission problem (401/403), or an address Gmail refuses.
// Everything else is "unknown", and the claim is kept so a repeat can't email twice.
const j = $input.first().json ?? {};
const e = j.error ?? j;
const text = (typeof e === 'string' ? e : JSON.stringify(e ?? {})).toLowerCase();
const httpCode = Number(e && (e.httpCode ?? e.statusCode ?? e.code));

const clearRejection =
  [400, 401, 403].includes(httpCode) ||
  /invalid (to|recipient)|recipient address required|invalid_grant|unauthorized|forbidden|invalid credentials|insufficient permission|the (credentials|access token) .*(invalid|expired|revoked)/.test(text);

return [
  {
    json: clearRejection
      ? { releaseClaim: true, code: 502, body: { status: 'failed', error: 'Gmail could not send the email' } }
      : { releaseClaim: false, code: 200, body: { status: 'unknown', error: 'The email may or may not have been sent' } },
  },
];

// n8n Code node "Restore failed response"  (Run Once for All Items)
// The Firestore "delete" node replaces the item, so re-read the answer decided earlier.
return [{ json: $('Classify Gmail error').first().json }];
